import csv, json, re
from datetime import datetime
from decimal import Decimal, ROUND_HALF_UP
rates = {k: Decimal(str(v)) for k, v in json.load(open('/data/rates.json')).items()}
rates['USD'] = Decimal(1)
def parse_date(s):
    for fmt in ('%Y-%m-%d', '%m/%d/%Y'):
        try:
            return datetime.strptime(s.strip(), fmt).date()
        except ValueError:
            pass
rejects, last = [], {}
with open('/data/sales.csv', newline='') as f:
    rd = csv.reader(f)
    next(rd)
    for line, (oid, date, region, cur, amount, status) in enumerate(rd, start=2):
        amt = amount.replace(',', '')
        d = parse_date(date)
        cur = cur.strip().upper()
        if not re.fullmatch(r'\d+(\.\d{1,2})?', amt) or cur not in rates or d is None:
            rejects.append(f'{line},{oid}')
            continue
        last.pop(oid, None)
        last[oid] = (d, region.strip().capitalize(), cur, Decimal(amt), status.strip().lower())
totals = {}
for d, region, cur, amt, status in last.values():
    if status == 'paid' and d.year == 2026 and d.month == 3:
        usd = (amt * rates[cur]).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        n, s = totals.get(region, (0, Decimal(0)))
        totals[region] = (n + 1, s + usd)
with open('/out/region_revenue.csv', 'w') as out:
    out.write('region,orders,revenue_usd\n')
    for region, (n, s) in sorted(totals.items(), key=lambda kv: (-kv[1][1], kv[0])):
        out.write(f'{region},{n},{s:.2f}\n')
    out.write(f"TOTAL,{sum(n for n, _ in totals.values())},{sum(s for _, s in totals.values()):.2f}\n")
with open('/out/rejects.txt', 'w') as out:
    out.write(''.join(r + '\n' for r in rejects))
EOF
