import csv, json, sys
rows, errors = [], []
with open('/data/events.jsonl', encoding='utf-8') as f:
    for n, line in enumerate(f, start=1):
        if not line.strip():
            continue
        try:
            obj = json.loads(line)
        except ValueError:
            errors.append(f'line {n}')
            continue
        if not isinstance(obj, dict):
            errors.append(f'line {n}')
            continue
        flat = {}
        stack = [('', obj)]
        def walk(prefix, d):
            for k, v in d.items():
                if isinstance(v, dict):
                    walk(prefix + k + '.', v)
                else:
                    flat[prefix + k] = v
        walk('', obj)
        rows.append(flat)
def fmt(v):
    if v is None: return ''
    if v is True: return 'true'
    if v is False: return 'false'
    if isinstance(v, str): return v
    if isinstance(v, list): return json.dumps(v, separators=(',', ':'), ensure_ascii=False)
    return json.dumps(v)
cols = sorted({k for r in rows for k in r})
with open('/out/events.csv', 'w', newline='', encoding='utf-8') as out:
    w = csv.writer(out, lineterminator='\n')
    w.writerow(cols)
    for r in rows:
        w.writerow([fmt(r.get(c)) for c in cols])
with open('/out/errors.txt', 'w') as out:
    out.write(''.join(e + '\n' for e in errors))
