from pathlib import Path
rows = []
for p in sorted(Path('/data/legacy').iterdir()):
    if not p.name.endswith('.txt'):
        continue
    raw = p.read_bytes()
    if raw[:2] in (b'\xff\xfe', b'\xfe\xff'):
        enc = 'utf-16'
    elif raw.startswith(b'\xef\xbb\xbf'):
        enc = 'utf-8-sig'
    else:
        try:
            raw.decode('utf-8')
            enc = 'utf-8'
        except UnicodeDecodeError:
            enc = 'latin-1'
    text = raw.decode(enc).replace('\r\n', '\n').replace('\r', '\n')
    if not text.endswith('\n'):
        text += '\n'
    Path('/out/clean', p.name).write_text(text, encoding='utf-8')
    rows.append(f'{p.name}\t{enc}\t{text.count(chr(10))}\t{len(text)}')
Path('/out/manifest.tsv').write_text('name\tencoding\tlines\tchars\n' + ''.join(r + '\n' for r in rows))
EOF
