import datetime, json, tomllib
from pathlib import Path
def merge(base, over):
    out = dict(base)
    for k, v in over.items():
        if v == '__unset__':
            out.pop(k, None)
        elif isinstance(v, dict) and isinstance(out.get(k), dict):
            out[k] = merge(out[k], v)
        else:
            out[k] = v
    return out
def plain(v):
    if isinstance(v, dict):
        return {k: plain(x) for k, x in v.items()}
    if isinstance(v, list):
        return [plain(x) for x in v]
    if isinstance(v, (datetime.date, datetime.time)):
        return v.isoformat()
    return v
base = tomllib.loads(Path('/config/base.toml').read_text())
names = []
for p in sorted(Path('/config/env').glob('*.toml')):
    cfg = plain(merge(base, tomllib.loads(p.read_text())))
    Path('/out', p.stem + '.json').write_text(json.dumps(cfg, indent=2, sort_keys=True, ensure_ascii=False) + '\n')
    names.append(p.stem)
Path('/out/index.txt').write_text(''.join(n + '\n' for n in names))
EOF
